/** `data/worldMap/satellite.json` (GENERATED by `scripts.wow_satellite.build`): which maps have a satellite view. */
export interface SatelliteManifest {
  /** The client build the images were made from — part of their URL. */
  build: string;
  width: number;
  height: number;
  /** UiMap ids, ascending. */
  maps: readonly number[];
}
